package com.srenterprises.configuration; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import org.springframework.boot.*; import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.*; import org.springframework.security.crypto.password.*;
@Configuration public class SeedConfiguration { @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder,@Value("${app.initial-admin-email}") String email,@Value("${app.initial-admin-password}") String password){return a->{if(!password.isBlank()&&users.findByEmailIgnoreCase(email).isEmpty()){User u=new User();u.email=email.toLowerCase();u.name="SR ENTERPRISES Administrator";u.passwordHash=encoder.encode(password);u.role=Role.SUPER_ADMIN;users.save(u);}};} }
